def move_tasks_to_individual_plans(apps, schema_editor):
    PlanTask = apps.get_model("work", "PlanTask")
    WorkPlan = apps.get_model("work", "WorkPlan")
    PlanDocument = apps.get_model("work", "PlanDocument")
    for task in PlanTask.objects.select_related("plan").iterator():
        source = task.plan
        description = task.title
        if task.description:
            description = f"{description}\n\n{task.description}"
        new_plan = WorkPlan.objects.create(
            site_id=source.site_id,
            worker_id=source.worker_id,
            work_date=source.work_date,
            description=description,
            status="planned",
            created_by_id=source.created_by_id,
        )
        for document in PlanDocument.objects.filter(plan_id=source.pk):
            PlanDocument.objects.create(plan_id=new_plan.pk, file=document.file.name)


